			/**
			 * 상세 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doDtl(psStatus) {
			    
			    //상세 조회 서브미션 호출
			    util.Submit.send(app, "subDtl", function(pbSuccess) {
			        if (pbSuccess) {
			            if (psStatus) {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			        }
			        
			        startDate = util.DataSet.getValue(app, "dsList", 0, "RSVT_BGNG_YMD").toString();
			        
			        startTime = util.DataSet.getValue(app, "dsList", 0, "RSVT_BGNG_HR").toString();
			        
			        endDate = util.DataSet.getValue(app, "dsList", 0, "RSVT_END_YMD").toString();
			        
			        endTime = util.DataSet.getValue(app, "dsList", 0, "RSVT_END_HR").toString();
			        
			        app.lookup("cmbStrTime2").selectItem(app.lookup("cmbStrTime2").getIndexByValue(startTime.substring(0, 2)));
			        app.lookup("cmbStrMin2").selectItem(app.lookup("cmbStrMin2").getIndexByValue(startTime.substring(2, 4)));
			        
			        app.lookup("cmbStrTime3").selectItem(app.lookup("cmbStrTime3").getIndexByValue(endTime.substring(0, 2)));
			        app.lookup("cmbStrMin3").selectItem(app.lookup("cmbStrMin3").getIndexByValue(endTime.substring(2, 4)));
			        
			        
			        util.DataSet.setValue(app, "dsList", 0, "DPCN_CHECK_START_TIME", startDate+startTime);
			        
			        console.log("##################################");
			        console.log(util.DataSet.getValue(app, "dsList", 0, "RESRCE_CL_MNG_ESNTAL_NO"));
			        console.log(util.DataSet.getValue(app, "dsList", 0, "RESRCE_NM"));
			        
			        util.DataSet.setValue(app, "dmDtlParam", "RESRCE_CL_MNG_LCLAS_SE_CD", util.DataSet.getValue(app, "dsList", 0, "RESRCE_CL_MNG_LCLAS_SE_CD"));
			        
			        // 자원분류관리목록요청
			        doResrceClMngList();
			        
			        // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			        util.Control.redraw(app, "grpBoardDtl");
			        
			        
			    });
			    
			    // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			    util.Control.redraw(app, "grpBoardDtl");
			}

			/**
			 * 날짜, 시간 VALIDATE 체크
			 */
			function saveValidateCheck(){
			    var dtiReqDate2 = app.lookup("dtiReqDate2");
			    var dtiReqDate3 = app.lookup("dtiReqDate3");
			    
			    var cmbStrTime2 = app.lookup("cmbStrTime2");
			    var cmbStrTime3 = app.lookup("cmbStrTime3");

			    var cmbStrMin2 = app.lookup("cmbStrMin2");
			    var cmbStrMin3 = app.lookup("cmbStrMin3");
			    
			    if(dtiReqDate2.value < moment().format("YYYYMMDD")){
			        util.Msg.alert(app, "시작일은 현재일과 같거나 커야합니다.", null, function(){
			            dtiReqDate2.focus();
			        });
			        return false;
			    }
			    
			    if(dtiReqDate3.value < dtiReqDate2.value ){
			        util.Msg.alert(app, "종료일은 시작일과 같거나 커야합니다.", null, function(){
			             dtiReqDate3.focus();
			        });
			        return false; 
			    }
			    
			    if(dtiReqDate2.value <= moment().format("YYYYMMDD")
			        && cmbStrTime2.value < moment().format("HH") ){
			        util.Msg.alert(app, "사용시작시간(시)을 확인해주세요.", null, function(){
			             cmbStrTime2.focus();
			        });
			        return false; 
			    }
			    
			    if(dtiReqDate2.value <= moment().format("YYYYMMDD") 
			        && cmbStrTime2.value <= moment().format("HH")
			        && cmbStrMin2.value < moment().format("mm") ){
			        util.Msg.alert(app, "사용시작시간(분)을 확인해주세요", null, function(){
			             cmbStrMin2.focus();
			        });
			        return false; 
			    }
			    
			    if(dtiReqDate3.value <= dtiReqDate2.value
			        && cmbStrTime3.value < cmbStrTime2.value ){
			        util.Msg.alert(app, "사용종료시간(시)을 확인해주세요.", null, function(){
			             cmbStrTime3.focus();
			        });
			        return false; 
			    }
			    
			    if(dtiReqDate3.value <= dtiReqDate2.value
			        && cmbStrTime3.value <= cmbStrTime2.value
			        && cmbStrMin3.value <= cmbStrMin2.value ){
			        util.Msg.alert(app, "사용종료시간(분)을 확인해주세요.", null, function(){
			             cmbStrMin3.focus();
			        });
			        return false; 
			    }
			    return true;
			}


			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "READ" | "UPDATE"} type 게시글 상세 조회 타입
			 */
			function setDtlCrud() {
			    
			    //console.log("setDtlCrud() -> viewType = " + viewType);
			    
			    var titleSeStr = "";
			    
			    if (viewType == "CREATE") {
			        
			        // 등록
			        titleSeStr = "등록";
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnClose"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			    } else if (viewType == "READ") {
			        
			        // 상세
			        titleSeStr = "상세";
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnUpdate", "btnDelete", "btnClose"]);
			        
			        util.Control.setReadOnly(app, true, "grpBoardDtl");
			        
			    } else if (viewType == "UPDATE") {
			        
			        // 수정
			        titleSeStr = "수정";
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnRestore", "btnClose"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			        // 자원대분류구분 및 자원은 수정 못하게 처리함
			        util.Control.setReadOnly(app, true, "cmb5");
			        util.Control.setReadOnly(app, true, "cmb3");
			        
			    }
			    
			    
			    //app.lookup("comFormTitle").title = "자원분류관리" + titleSeStr;
			    //app.lookup("grpBoardDtl").fieldLabel = "자원분류관리" + titleSeStr;
			    
			    
			    // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			    util.Control.redraw(app, "comFormTitle");
			    //util.Control.redraw(app, "grpBoardDtl");
			    
			}


