			/**
			 * 사용시작일, 종료일 입력사항 체크
			 */
			function useDateValidate(pcCtrl) {
			    console.log("useDateValidate : " +startDate + "~" + endDate);
			    
			    if(Number(startDate) < Number(sysDate)){  
			         util.Msg.alert(app, "시작일은 현재일과 같거나 커야합니다.", null, function(){
			             pcCtrl.focus();
			         });
			         return false;         
			    } 

			    if(Number(startDate) > Number(endDate)){
			        
			        util.Msg.alert(app, "종료일은 시작일과 같거나 커야합니다.", null, function(){
			             pcCtrl.focus();
			         });
			         return false; 
			         
			    }
			    
			    
			    return true;
			    
			}


			/**
			 * 사용시작,종료시간 입력사항 체크
			 */
			function beforeUseTimeValidate(pcCtrl){
			       
			    var vdBeforeStrTime = moment(beforeStrTime);
			    var vdBeforeEndTime = moment(beforeEndTime);
			        
			    var vsStrTime = app.lookup("cmbStrTime2").value;
			    var vsEndTime = app.lookup("cmbStrTime3").value;
			    
			    var vsStrMin = app.lookup("cmbStrMin2").value;
			    var vsEndMin = app.lookup("cmbStrMin3").value;
			    
			    if(pcCtrl.id == "cmbStrTime2"){
			        
			        if(ValueUtil.isNull(vsEndTime)) return true;
			        
			        if(vdBeforeStrTime.format("HH") == vdBeforeEndTime.format("HH") &&
			            ValueUtil.isNull(vsStrMin)) return true;
			        
			    } else if(pcCtrl.id == "cmbStrTime3"){
			      
			        if(ValueUtil.isNull(vsStrTime)) return true;
			        
			        if(vdBeforeStrTime.format("HH") == vdBeforeEndTime.format("HH") &&
			           ValueUtil.isNull(vsEndMin)) return true;           
			        
			    } else if(pcCtrl.id == "cmbStrMin2"){
			        if(ValueUtil.isNull(vsStrTime) || ValueUtil.isNull(vsEndTime)) return true;
			        
			        if(ValueUtil.isNull(vsEndMin)) return true;
			           
			    } else {
			        if(ValueUtil.isNull(vsStrTime) || ValueUtil.isNull(vsEndTime)) return true;
			        
			        if(ValueUtil.isNull(vsStrMin)) return true;
			    }
			    
			    
			    if(startDate == endDate){
			        
			        if(vdBeforeStrTime.format("HHmm") >= vdBeforeEndTime.format("HHmm")){
			             util.Msg.alert(app, "종료시간은 시작시간 보다 커야합니다.", null, function(){
			                 pcCtrl.focus();
			             });
			             return false;         
			        } 
			    
			    }
			    
			    
			    return true;     
			}


