			async function onBtnSaveClick2(e){
			    var btnSave = e.control;
			    
			    if(app.lookup("dsResrceClMngLclasSeCd").getRowCount() == 0){
			        util.Msg.alert(app, "등록된 시설및물품 정보가 없습니다.\n공통코드에 시설및물품을 등록 해주세요.");
			        return false;
			    }

			    if(app.lookup("cmb3").value == "선택"){
			        if(app.lookup("dsResrceClMngList").getRowCount() == 0){
			            util.Msg.alert(app, "등록된 시설및물품 명칭 정보가 없습니다.\n시설및물품종류 등록을 해주세요.");
			            return false;
			        }
			    }else{
			        if(app.lookup("dsResrceClMngList").getRowCount() == 0){
			            util.Msg.alert(app, "등록된 선택한 시설및물품에 명칭 정보가 없습니다.\n시설및물품종류 등록을 해주세요.");
			            return false;
			        }
			    }
			    
			    
			    var valCheck = await saveValidateCheck();
			    if(valCheck){
			        util.Msg.confirm(app, "CRM-M001", null, function() {
			            
			            dataSetUseTime();
			            doResrceRsvtDpcnChk();
			    //        doSave();
			        });
			    }
			}


